<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>@yield('title') · {{ $identidad->name }}</title><style>:root{--p:{{ $identidad->primary_color }};--dark:{{ $identidad->sidebar_color }};--line:#dfe7e3;--muted:#68776f;--bg:#f4f7f5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#17231e;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.top{background:var(--dark);color:#fff;padding:18px 0}.wrap{width:min(1100px,calc(100% - 28px));margin:auto}.top .wrap{display:flex;justify-content:space-between}.brand{font-weight:850;font-size:18px}.back{color:#c8d9d2;text-decoration:none;font-size:13px}main{padding:30px 0}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.head h1{margin:0 0 4px;font-size:26px}.head p{margin:0;color:var(--muted);font-size:13px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;box-shadow:0 10px 30px rgba(20,40,30,.06)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.full{grid-column:1/-1}label{display:block;font-size:12px;font-weight:750;margin-bottom:7px}input,select,textarea{width:100%;border:1px solid #c9d6d0;border-radius:9px;padding:11px 12px;font:inherit;font-size:13px}textarea{min-height:100px}.check{display:flex;gap:8px;align-items:center}.check input{width:auto}.check label{margin:0}.btn{display:inline-block;border:0;border-radius:9px;padding:10px 15px;background:var(--p);color:#fff;text-decoration:none;font-size:13px;font-weight:750;cursor:pointer}.btn.light{background:#edf2ef;color:#293830}.btn.red{background:#fff0ee;color:#b83c32}.actions{display:flex;justify-content:flex-end;gap:8px;border-top:1px solid var(--line);padding-top:18px;margin-top:20px}.alert{padding:12px 15px;border-radius:9px;background:#e7f8ef;color:#087447;margin-bottom:14px;font-size:13px}.alert.error{background:#fff0ee;color:#a9362c}.error{font-size:11px;color:#bd4035;margin-top:4px}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:var(--muted);font-size:10px;text-transform:uppercase;padding:11px}td{padding:13px 11px;border-top:1px solid var(--line)}.pill{padding:5px 9px;border-radius:20px;background:#e8f7ef;color:#087447;font-size:10px;font-weight:800}.pill.off{background:#f0f1f1;color:#68716d}.row-actions{display:flex;gap:6px}.row-actions form{margin:0}.filter{display:flex;gap:8px;margin-bottom:16px}.detail{padding:11px;border:1px solid var(--line);border-radius:9px}.detail small,.detail strong{display:block}.detail small{color:var(--muted);font-size:10px;margin-bottom:3px}.colors{display:flex;gap:9px;align-items:center}.colors input[type=color]{width:55px;padding:3px;height:42px}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.head{align-items:flex-start}.card{padding:16px}th:nth-child(2),td:nth-child(2){display:none}}</style></head><body><header class="top"><div class="wrap"><div class="brand">✦ {{ $identidad->name }}</div><a class="back" href="{{ url('/') }}">← Volver al panel</a></div></header><main class="wrap">@if(session('success'))<div class="alert">{{ session('success') }}</div>@endif @if(session('error'))<div class="alert error">{{ session('error') }}</div>@endif @yield('content')</main></body></html>
